actions.script:
const marketing=ec.resource.script('component://mr-pass/screen/Marketing/Marketing.js'),p=ec.web.parameters
const page=marketing.base(publicPath,'submit')
const token=marketing.param('token'),publication=marketing.param('publication')
// the answers of the questions the page showed, by name (a checkbox group sends several)
const names=String(marketing.param('fieldNames') || '').split(',').map(s=>s.trim()).filter(s=>/^[A-Za-z][A-Za-z0-9_]{0,59}$/.test(s))
const values={}
for(const name of names){
    const value=p['f_'+name]
    if(value==null || value==='')continue
    values[name]=Array.isArray(value)?value.map(String):(typeof value==='object' && value.length!=null?Array.from(value).map(String):String(value))
}
const back={path:page,params:{publication,token}}
marketing.post('submitMarketingForm',{siteId:resolvedSiteId,publicationId:publication,token,values:JSON.stringify(values),
    subscribe:marketing.param('subscribe'),subscriptionEmail:marketing.param('subscriptionEmail'),operationId:marketing.param('operationId')},
    back,{path:page,params:{publication,token,sent:'1'}})

const marketing=ec.resource.script('component://mr-pass/screen/Marketing/Marketing.js')
flash=marketing.take()
token=marketing.param('token')
publicationParam=marketing.param('publication')
view=null;failure=null
if(!token && !publicationParam)failure={kind:'NotFound',message:ec.l10n.localize("Open this page from the link you were given.")}
else{
    const found=marketing.portal.attempt('getMarketingForm',{siteId:resolvedSiteId,...(token ? {token} : {publicationId:publicationParam})})
    if(found.error)failure=found.error.kind==='NotFound'?{kind:'NotFound',message:ec.l10n.localize("This form is not available. It may have closed, or the link may have expired.")}:found.error
    else view=found.result
}
// the receipt shows after a post, never on a plain visit
receipt=marketing.param('sent') ? (flash.receipt || null) : null
const ruleText=(rule)=>rule?JSON.stringify({form:'PublicForm',field:'f_'+rule.field,operator:rule.operator,values:rule.values || []}):''
formFields=view?(view.form.fields || []).map(f=>Object.assign({},f,{showText:ruleText(f.show),requireText:ruleText(f.require)})):[]
fieldNames=formFields.map(f=>f.fieldName).join(',')
submitOperationId=marketing.portal.operationId()
